SELECT CAST(SUM(IIF(customers.currency = '欧元', 1, 0)) AS REAL) / SUM(IIF(customers.currency = '捷克克朗', 1, 0)) AS ratio FROM customers AS customers	debit_card_specializing
SELECT AVG(t2.consumption) / 12 AS _col_0 FROM customers AS t1 INNER JOIN yearmonth AS t2 ON t1.customerid = t2.customerid WHERE SUBSTRING(t2.date, 1, 4) = '2013' AND t1.segment = '中小企业'	debit_card_specializing
SELECT SUM(IIF(t1.currency = '捷克克朗', t2.consumption, 0)) - SUM(IIF(t1.currency = '欧元', t2.consumption, 0)) AS _col_0 FROM customers AS t1 INNER JOIN yearmonth AS t2 ON t1.customerid = t2.customerid WHERE SUBSTRING(t2.date, 1, 4) = '2012'	debit_card_specializing
SELECT CAST(SUM(IIF(t1.segment = '中小企业', t2.consumption, 0)) AS REAL) / COUNT(t1.customerid) - CAST(SUM(IIF(t1.segment = 'LAM', t2.consumption, 0)) AS REAL) / COUNT(t1.customerid) AS _col_0, CAST(SUM(IIF(t1.segment = 'LAM', t2.consumption, 0)) AS REAL) / COUNT(t1.customerid) - CAST(SUM(IIF(t1.segment = 'KAM', t2.consumption, 0)) AS REAL) / COUNT(t1.customerid) AS _col_1, CAST(SUM(IIF(t1.segment = 'KAM', t2.consumption, 0)) AS REAL) / COUNT(t1.customerid) - CAST(SUM(IIF(t1.segment = '中小企业', t2.consumption, 0)) AS REAL) / COUNT(t1.customerid) AS _col_2 FROM customers AS t1 INNER JOIN yearmonth AS t2 ON t1.customerid = t2.customerid WHERE t1.currency = '捷克克朗' AND t2.consumption = (SELECT MIN(yearmonth.consumption) AS _col_0 FROM yearmonth AS yearmonth) AND t2.date BETWEEN 201301 AND 201312	debit_card_specializing
SELECT CAST((SUM(IIF(t1.segment = '中小企业' AND t2.date LIKE '2013%', t2.consumption, 0)) - SUM(IIF(t1.segment = '中小企业' AND t2.date LIKE '2012%', t2.consumption, 0))) AS REAL) * 100 / SUM(IIF(t1.segment = '中小企业' AND t2.date LIKE '2012%', t2.consumption, 0)) AS _col_0, CAST(SUM(IIF(t1.segment = 'LAM' AND t2.date LIKE '2013%', t2.consumption, 0)) - SUM(IIF(t1.segment = 'LAM' AND t2.date LIKE '2012%', t2.consumption, 0)) AS REAL) * 100 / SUM(IIF(t1.segment = 'LAM' AND t2.date LIKE '2012%', t2.consumption, 0)) AS _col_1, CAST(SUM(IIF(t1.segment = 'KAM' AND t2.date LIKE '2013%', t2.consumption, 0)) - SUM(IIF(t1.segment = 'KAM' AND t2.date LIKE '2012%', t2.consumption, 0)) AS REAL) * 100 / SUM(IIF(t1.segment = 'KAM' AND t2.date LIKE '2012%', t2.consumption, 0)) AS _col_2 FROM customers AS t1 INNER JOIN yearmonth AS t2 ON t1.customerid = t2.customerid	debit_card_specializing
SELECT SUM(IIF(gasstations.country = 'CZE', 1, 0)) - SUM(IIF(gasstations.country = 'SVK', 1, 0)) AS _col_0 FROM gasstations AS gasstations WHERE gasstations.segment = '折扣型'	debit_card_specializing
SELECT CAST(SUM(IIF(yearmonth.consumption > 528.3, 1, 0)) AS REAL) * 100 / COUNT(yearmonth.customerid) AS _col_0 FROM yearmonth AS yearmonth WHERE yearmonth.date = '201202'	debit_card_specializing
SELECT CAST(SUM(IIF(t2.currency = '欧元', 1, 0)) AS REAL) * 100 / COUNT(t1.customerid) AS _col_0 FROM transactions_1k AS t1 INNER JOIN customers AS t2 ON t1.customerid = t2.customerid WHERE t1.date = '2012-08-25'	debit_card_specializing
SELECT CAST(SUM(IIF(gasstations.country = 'SVK' AND gasstations.segment = '高端型', 1, 0)) AS REAL) * 100 / SUM(IIF(gasstations.country = 'SVK', 1, 0)) AS _col_0 FROM gasstations AS gasstations	debit_card_specializing
SELECT t2.amount AS amount FROM member AS t1 INNER JOIN income AS t2 ON t1.member_id = t2.link_to_member WHERE t1.position = '副主席'	student_club
SELECT income.notes AS notes FROM income AS income WHERE income.source = '筹款' AND income.date_received = '2019-09-14'	student_club
SELECT t1.event_status AS event_status FROM budget AS t1 INNER JOIN expense AS t2 ON t1.budget_id = t2.link_to_budget WHERE t2.expense_description = '明信片、海报' AND t2.expense_date = '2019-08-20'	student_club
SELECT COUNT(t1.member_id) AS _col_0 FROM member AS t1 INNER JOIN major AS t2 ON t1.link_to_major = t2.major_id WHERE t2.major_name = 'Business' AND t1.t_shirt_size = '中号'	student_club
SELECT CAST(SUM(CASE WHEN t2.event_name = 'Yearly Kickoff' THEN t1.amount ELSE 0 END) AS REAL) / SUM(CASE WHEN t2.event_name = 'October Meeting' THEN t1.amount ELSE 0 END) AS _col_0 FROM budget AS t1 INNER JOIN event AS t2 ON t1.link_to_event = t2.event_id WHERE t1.category = '宣传推广' AND t2.type = '会议'	student_club
SELECT SUM(expense.cost) AS _col_0 FROM expense AS expense WHERE expense.expense_description = '披萨'	student_club
SELECT t1.first_name AS first_name, t1.last_name AS last_name FROM member AS t1 INNER JOIN major AS t2 ON t1.link_to_major = t2.major_id WHERE t2.department = '应用科学、技术与教育学院'	student_club
SELECT SUM(budget.spent) AS _col_0 FROM budget AS budget WHERE budget.category = '餐饮'	student_club
SELECT t2.first_name AS first_name, t2.last_name AS last_name, t1.cost AS cost FROM expense AS t1 INNER JOIN member AS t2 ON t1.link_to_member = t2.member_id WHERE t1.expense_description = '矿泉水、蔬菜拼盘、耗材'	student_club
SELECT SUM(CASE WHEN patient.admission = '+' THEN 1.0 ELSE 0 END) / SUM(CASE WHEN patient.admission = '-' THEN 1 ELSE 0 END) AS _col_0 FROM patient AS patient WHERE patient.diagnosis = '系统性红斑狼疮'	thrombosis_prediction
SELECT t1.date AS date, STRFTIME('%Y', t2."first date") - STRFTIME('%Y', t2.birthday) AS _col_1, t2.birthday AS birthday FROM laboratory AS t1 INNER JOIN patient AS t2 ON t1.id = t2.id WHERE t2.diagnosis = '史蒂文斯-约翰逊综合征' AND NOT t2.birthday IS NULL ORDER BY t2.birthday ASC LIMIT 1	thrombosis_prediction
SELECT examination."acl iga" AS "acl iga", examination."acl igg" AS "acl igg", examination."acl igm" AS "acl igm" FROM examination AS examination WHERE examination.id IN (SELECT patient.id AS id FROM patient AS patient WHERE patient.diagnosis = '系统性红斑狼疮' AND patient.description = '1994-02-19') AND examination."examination date" = '1993-11-12'	thrombosis_prediction
SELECT COUNT(patient.id) AS _col_0 FROM patient AS patient WHERE patient.sex = 'F' AND patient.diagnosis = '抗磷脂综合征'	thrombosis_prediction
SELECT CAST(SUM(CASE WHEN patient.sex = 'F' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(patient.id) AS _col_0 FROM patient AS patient WHERE patient.diagnosis = '类风湿关节炎' AND STRFTIME('%Y', patient.birthday) = '1980'	thrombosis_prediction
SELECT t1.id AS id, t1.sex AS sex FROM patient AS t1 INNER JOIN laboratory AS t2 ON t1.id = t2.id WHERE t1.diagnosis = '系统性红斑狼疮' AND t2.hgb > 10 AND t2.hgb < 17 ORDER BY t1.birthday ASC LIMIT 1	thrombosis_prediction
SELECT COUNT(t1.id) AS _col_0 FROM patient AS t1 INNER JOIN laboratory AS t2 ON t1.id = t2.id INNER JOIN examination AS t3 ON t3.id = t2.id WHERE t2.igg BETWEEN 900 AND 2000 AND NOT t3.symptoms IS NULL	thrombosis_prediction
SELECT COUNT(t1.id) AS _col_0 FROM examination AS t1 INNER JOIN laboratory AS t2 ON t1.id = t2.id WHERE t2.sm IN ('阴性', '0') AND t1.thrombosis = 0	thrombosis_prediction
SELECT COUNT(DISTINCT t1.id) AS _col_0 FROM patient AS t1 INNER JOIN laboratory AS t2 ON t1.id = t2.id INNER JOIN examination AS t3 ON t3.id = t2.id WHERE (t2.sc170 = '阴性' OR t2.sc170 = '0') AND t1.sex = 'F' AND t3.symptoms IS NULL	thrombosis_prediction
SELECT CAST(COUNT(CASE WHEN t2.preferred_foot = '左脚' THEN t1.id ELSE NULL END) AS REAL) * 100 / COUNT(t1.id) AS percent FROM player AS t1 INNER JOIN player_attributes AS t2 ON t1.player_api_id = t2.player_api_id WHERE SUBSTRING(t1.birthday, 1, 4) BETWEEN '1987' AND '1992'	european_football_2
SELECT t1.player_name AS player_name FROM player AS t1 INNER JOIN player_attributes AS t2 ON t1.player_api_id = t2.player_api_id WHERE t1.height > 180 GROUP BY t1.id ORDER BY CAST(SUM(t2.heading_accuracy) AS REAL) / COUNT(t2."player_fifa_api_id") DESC LIMIT 10	european_football_2
SELECT COUNT(DISTINCT t1.player_name) AS _col_0 FROM player AS t1 INNER JOIN player_attributes AS t2 ON t1.player_api_id = t2.player_api_id WHERE STRFTIME('%Y', t1.birthday) < '1986' AND t2.defensive_work_rate = '高'	european_football_2
SELECT _0.player_name AS player_name FROM (SELECT player.player_name AS player_name, player.height AS height, DENSE_RANK() OVER (ORDER BY player.height DESC) AS rank FROM player AS player) AS _0 WHERE _0.rank = 1	european_football_2
SELECT DISTINCT t1.team_short_name AS team_short_name FROM team AS t1 INNER JOIN team_attributes AS t2 ON t1.team_api_id = t2.team_api_id WHERE t2.chancecreationpassingclass = '低风险'	european_football_2
SELECT SUM(CASE WHEN t1.id = 6 THEN t1.jumping ELSE 0 END) - SUM(CASE WHEN t1.id = 23 THEN t1.jumping ELSE 0 END) AS _col_0 FROM player_attributes AS t1	european_football_2
SELECT COUNT(t1.id) AS _col_0 FROM player_attributes AS t1 WHERE t1.preferred_foot = '左脚' AND t1.crossing = (SELECT MAX(player_attributes.crossing) AS _col_0 FROM player_attributes AS player_attributes)	european_football_2
SELECT CAST(COUNT(CASE WHEN t2.overall_rating > 70 AND t1.height < 180 THEN t1.id ELSE NULL END) AS REAL) * 100 / COUNT(t1.id) AS percent FROM player AS t1 INNER JOIN player_attributes AS t2 ON t1.player_api_id = t2.player_api_id	european_football_2
SELECT t1.forename AS forename, t1.surname AS surname FROM drivers AS t1 INNER JOIN results AS t2 ON t2.driverid = t1.driverid WHERE t2.raceid = 872 AND NOT t2.time IS NULL ORDER BY t1.dob DESC LIMIT 1	formula_1
SELECT STRFTIME('%Y', CURRENT_TIMESTAMP) - STRFTIME('%Y', drivers.dob) AS _col_0, drivers.forename AS forename, drivers.surname AS surname FROM drivers AS drivers WHERE drivers.nationality = '日本籍' ORDER BY drivers.dob DESC LIMIT 1	formula_1
SELECT MAX(t1.points) AS _col_0 FROM constructorstandings AS t1 INNER JOIN constructors AS t2 ON t1.constructorid = t2.constructorid WHERE t2.nationality = '英国籍'	formula_1
SELECT COUNT(t1.raceid) AS _col_0 FROM constructorstandings AS t1 INNER JOIN constructors AS t2 ON t1.constructorid = t2.constructorid WHERE t1.points = 0 AND t2.nationality = '日本籍' GROUP BY t1.constructorid HAVING COUNT(t1.raceid) = 2	formula_1
SELECT CAST(SUM(IIF(NOT t1.time IS NULL, 1, 0)) AS REAL) * 100 / COUNT(t1.raceid) AS _col_0 FROM results AS t1 INNER JOIN races AS t2 ON t1.raceid = t2.raceid INNER JOIN drivers AS t3 ON t1.driverid = t3.driverid WHERE t3.nationality = '日本籍' AND t2.year BETWEEN 2007 AND 2009	formula_1
SELECT COUNT(t1.driverid) AS _col_0 FROM drivers AS t1 INNER JOIN laptimes AS t2 ON t1.driverid = t2.driverid WHERE t1.nationality = '法国籍' AND (CAST(SUBSTRING(t2.time, 1, 2) AS INTEGER) * 60 + CAST(SUBSTRING(t2.time, 4, 2) AS INTEGER) + CAST(SUBSTRING(t2.time, 7, 2) AS REAL) / 1000) < 120	formula_1
SELECT t3.year AS year, t3.name AS name, t3.date AS date, t3.time AS time FROM qualifying AS t1 INNER JOIN drivers AS t2 ON t1.driverid = t2.driverid INNER JOIN races AS t3 ON t1.raceid = t3.raceid WHERE t1.driverid = (SELECT drivers.driverid AS driverid FROM drivers AS drivers ORDER BY drivers.dob DESC LIMIT 1) ORDER BY t3.date ASC LIMIT 1	formula_1
SELECT t2.forename AS forename, t2.surname AS surname FROM pitstops AS t1 INNER JOIN drivers AS t2 ON t1.driverid = t2.driverid WHERE t2.nationality = '德国籍' AND STRFTIME('%Y', t2.dob) BETWEEN '1980' AND '1985' GROUP BY t2.forename, t2.surname ORDER BY AVG(t1.duration) LIMIT 3	formula_1
SELECT t1.forename AS forename, t1.surname AS surname, t1.nationality AS nationality, t3.name AS name FROM drivers AS t1 INNER JOIN driverstandings AS t2 ON t1.driverid = t2.driverid INNER JOIN races AS t3 ON t2.raceid = t3.raceid ORDER BY JULIANDAY(t1.dob) DESC LIMIT 1	formula_1
SELECT t1.superhero_name AS superhero_name FROM superhero AS t1 INNER JOIN colour AS t2 ON t1.eye_colour_id = t2.id INNER JOIN colour AS t3 ON t1.hair_colour_id = t3.id WHERE t2.colour = '蓝色' AND t3.colour = '金发色'	superhero
SELECT COUNT(t1.id) AS _col_0 FROM superhero AS t1 INNER JOIN hero_attribute AS t2 ON t1.id = t2.hero_id INNER JOIN attribute AS t3 ON t2.attribute_id = t3.id INNER JOIN gender AS t4 ON t1.gender_id = t4.id WHERE t3.attribute_name = 'Strength' AND t2.attribute_value = 100 AND t4.gender = '女性'	superhero
SELECT AVG(t1.weight_kg) AS _col_0 FROM superhero AS t1 INNER JOIN gender AS t2 ON t1.gender_id = t2.id WHERE t2.gender = '女性'	superhero
SELECT DISTINCT t1.superhero_name AS superhero_name FROM superhero AS t1 INNER JOIN colour AS t2 ON t1.eye_colour_id = t2.id WHERE t1.height_cm BETWEEN 170 AND 190 AND t2.colour = '无颜色'	superhero
SELECT t1.eye_colour_id AS eye_colour_id, t1.hair_colour_id AS hair_colour_id, t1.skin_colour_id AS skin_colour_id FROM superhero AS t1 INNER JOIN publisher AS t2 ON t2.id = t1.publisher_id INNER JOIN gender AS t3 ON t3.id = t1.gender_id WHERE t2.publisher_name = 'Dark Horse Comics' AND t3.gender = '女性'	superhero
SELECT t1.height_cm AS height_cm FROM superhero AS t1 INNER JOIN colour AS t2 ON t1.eye_colour_id = t2.id WHERE t2.colour = '琥珀色'	superhero
SELECT t1.superhero_name AS superhero_name FROM superhero AS t1 INNER JOIN alignment AS t2 ON t1.alignment_id = t2.id WHERE t2.alignment = '中立'	superhero
SELECT t1.superhero_name AS superhero_name FROM superhero AS t1 INNER JOIN colour AS t2 ON t1.eye_colour_id = t2.id INNER JOIN colour AS t3 ON t1.hair_colour_id = t3.id WHERE t2.colour = '蓝色' AND t3.colour = '棕色'	superhero
SELECT CAST(COUNT(CASE WHEN t2.gender = '男性' THEN t1.id ELSE NULL END) AS REAL) / COUNT(CASE WHEN t2.gender = '女性' THEN t1.id ELSE NULL END) AS _col_0 FROM superhero AS t1 INNER JOIN gender AS t2 ON t1.gender_id = t2.id	superhero
SELECT CAST(SUM(IIF(t2.age > 65, 1, 0)) AS REAL) * 100 / COUNT(t1.id) AS _col_0 FROM posts AS t1 INNER JOIN users AS t2 ON t1.owneruserid = t2.id WHERE t1.score > 5	codebase_community
SELECT t1.favoritecount AS favoritecount FROM posts AS t1 INNER JOIN comments AS t2 ON t1.id = t2.postid WHERE t2.creationdate = '2014-04-23 20:29:39.0' AND t2.userid = 3025	codebase_community
SELECT COUNT(t1.id) AS _col_0 FROM users AS t1 INNER JOIN posts AS t2 ON t1.id = t2.owneruserid WHERE t1.displayname = 'Tiago Pasqualini'	codebase_community
SELECT t1.displayname AS displayname FROM users AS t1 INNER JOIN votes AS t2 ON t1.id = t2.userid WHERE t2.id = 6347	codebase_community
SELECT t2.userid AS userid FROM users AS t1 INNER JOIN posthistory AS t2 ON t1.id = t2.userid INNER JOIN posts AS t3 ON t2.postid = t3.id WHERE t3.viewcount >= 1000 GROUP BY t2.userid HAVING COUNT(DISTINCT t2.posthistorytypeid) = 1	codebase_community
SELECT AVG(t1.upvotes) AS _col_0, AVG(t1.age) AS _col_1 FROM users AS t1 INNER JOIN (SELECT posts.owneruserid AS owneruserid, COUNT(*) AS post_count FROM posts AS posts GROUP BY posts.owneruserid HAVING COUNT(*) > 10) AS t2 ON t1.id = t2.owneruserid	codebase_community
SELECT COUNT(t2.id) AS _col_0 FROM posts AS t1 INNER JOIN comments AS t2 ON t1.id = t2.postid GROUP BY t1.id ORDER BY t1.score DESC LIMIT 1	codebase_community
SELECT CAST(SUM(CASE WHEN t2.score > 50 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(t1.id) AS _col_0 FROM users AS t1 INNER JOIN posts AS t2 ON t1.id = t2.owneruserid WHERE t1.reputation = (SELECT MAX(users.reputation) AS _col_0 FROM users AS users)	codebase_community
SELECT id AS id FROM cards AS cards WHERE cards.bordercolor = '无边框' AND (cards.cardkingdomid IS NULL OR cards.cardkingdomid IS NULL)	card_games
SELECT DISTINCT t1.id AS id FROM cards AS t1 INNER JOIN legalities AS t2 ON t1.uuid = t2.uuid WHERE t2.format = '角斗士赛制' AND t2.status = '禁用' AND t1.rarity = '神话'	card_games
SELECT DISTINCT t2.status AS status FROM cards AS t1 INNER JOIN legalities AS t2 ON t1.uuid = t2.uuid WHERE t1.type = 'Artifact' AND t2.format = '经典赛制' AND t1.side IS NULL	card_games
SELECT CAST(SUM(CASE WHEN t2.language = '简体中文' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(t1.id) AS _col_0 FROM cards AS t1 INNER JOIN foreign_data AS t2 ON t1.uuid = t2.uuid	card_games
SELECT CAST(SUM(CASE WHEN t2.language = '法语' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(t1.id) AS _col_0 FROM cards AS t1 INNER JOIN foreign_data AS t2 ON t1.uuid = t2.uuid WHERE t1.isstoryspotlight = 1	card_games
SELECT CAST(SUM(CASE WHEN cards.istextless = 0 AND cards.isstoryspotlight = 1 THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(id) AS _col_0 FROM cards AS cards	card_games
SELECT t2.language AS language FROM sets AS t1 INNER JOIN set_translations AS t2 ON t1.code = t2.setcode WHERE t1.block = '拉尼卡' AND t1.basesetsize = 180	card_games
SELECT CAST(SUM(CASE WHEN t2.language = '法语' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(t1.id) AS _col_0 FROM cards AS t1 INNER JOIN foreign_data AS t2 ON t1.uuid = t2.uuid WHERE t1.power IS NULL OR t1.power = '*'	card_games
SELECT COUNT(DISTINCT t1.id) AS _col_0 FROM sets AS t1 INNER JOIN set_translations AS t2 ON t2.setcode = t1.code WHERE t1.block = '冰封时代' AND t2.language = '意大利语' AND NOT t2.translation IS NULL	card_games
SELECT CAST(COUNT(DISTINCT CASE WHEN t1.element = '碳' THEN t1.atom_id ELSE NULL END) AS REAL) * 100 / COUNT(DISTINCT t1.atom_id) AS _col_0 FROM atom AS t1 INNER JOIN bond AS t2 ON t1.molecule_id = t2.molecule_id WHERE t2.bond_type = '='	toxicology
SELECT COUNT(DISTINCT CASE WHEN t1.element = '碘' THEN t1.atom_id ELSE NULL END) AS iodine_nums, COUNT(DISTINCT CASE WHEN t1.element = '硫' THEN t1.atom_id ELSE NULL END) AS sulfur_nums FROM atom AS t1 INNER JOIN connected AS t2 ON t1.atom_id = t2.atom_id INNER JOIN bond AS t3 ON t2.bond_id = t3.bond_id WHERE t3.bond_type = '-'	toxicology
SELECT ROUND(CAST(COUNT(CASE WHEN t.element = '氢' THEN t.atom_id ELSE NULL END) AS REAL) * 100 / COUNT(t.atom_id), 4) AS _col_0 FROM atom AS t WHERE t.molecule_id = 'TR206'	toxicology
SELECT t2.bond_id AS bond_id FROM atom AS t1 INNER JOIN connected AS t2 ON t1.atom_id = t2.atom_id WHERE t2.bond_id IN (SELECT t3.bond_id AS bond_id FROM connected AS t3 INNER JOIN atom AS t4 ON t3.atom_id = t4.atom_id WHERE t4.element = '磷') AND t1.element = '氮'	toxicology
SELECT CAST(COUNT(t2.bond_id) AS REAL) / COUNT(t1.atom_id) AS _col_0 FROM atom AS t1 INNER JOIN connected AS t2 ON t1.atom_id = t2.atom_id WHERE t1.element = '碘'	toxicology
SELECT DISTINCT t.element AS element FROM atom AS t WHERE NOT t.element IN (SELECT DISTINCT t1.element AS element FROM atom AS t1 INNER JOIN connected AS t2 ON t1.atom_id = t2.atom_id)	toxicology
SELECT COUNT(t1.atom_id) AS _col_0 FROM atom AS t1 INNER JOIN molecule AS t2 ON t1.molecule_id = t2.molecule_id INNER JOIN bond AS t3 ON t2.molecule_id = t3.molecule_id WHERE t3.bond_type = '#' AND t1.element IN ('磷', '溴')	toxicology
SELECT CAST(COUNT(CASE WHEN t1.element = '氯' THEN t1.element ELSE NULL END) AS REAL) * 100 / COUNT(t1.element) AS _col_0 FROM atom AS t1 INNER JOIN molecule AS t2 ON t1.molecule_id = t2.molecule_id WHERE t2.label = '+'	toxicology
WITH subquery AS (SELECT DISTINCT t1.atom_id AS atom_id, t1.element AS element, t1.molecule_id AS molecule_id, t2.label AS label FROM atom AS t1 INNER JOIN molecule AS t2 ON t1.molecule_id = t2.molecule_id WHERE t2.molecule_id = 'TR006') SELECT CAST(COUNT(CASE WHEN subquery.element = '氢' THEN subquery.atom_id ELSE NULL END) AS REAL) / (CASE WHEN COUNT(subquery.atom_id) = 0 THEN NULL ELSE COUNT(subquery.atom_id) END) AS ratio, subquery.label AS label FROM subquery AS subquery GROUP BY subquery.label	toxicology
SELECT t2.cdscode AS cdscode FROM schools AS t1 INNER JOIN frpm AS t2 ON t1.cdscode = t2.cdscode WHERE t2."enrollment (k-12)" + t2."enrollment (ages 5-17)" > 500	california_schools
SELECT t1."school name" AS "school name", t2.street AS street, t2.city AS city, t2.state AS state, t2.zip AS zip FROM frpm AS t1 INNER JOIN schools AS t2 ON t1.cdscode = t2.cdscode WHERE t2.county = 'Monterey' AND t1."free meal count (ages 5-17)" > 800 AND t1."school type" = '高中（公立）'	california_schools
SELECT t2.school AS school, t2.doc AS doc FROM frpm AS t1 INNER JOIN schools AS t2 ON t1.cdscode = t2.cdscode WHERE t2.fundingtype = '地方资助' AND (t1."enrollment (k-12)" - t1."enrollment (ages 5-17)") > (SELECT AVG(t3."enrollment (k-12)" - t3."enrollment (ages 5-17)") AS _col_0 FROM frpm AS t3 INNER JOIN schools AS t4 ON t3.cdscode = t4.cdscode WHERE t4.fundingtype = '地方资助')	california_schools
SELECT CAST(t1."frpm count (k-12)" AS REAL) / t1."enrollment (k-12)" AS _col_0 FROM frpm AS t1 INNER JOIN schools AS t2 ON t1.cdscode = t2.cdscode WHERE t2.soc = 66 ORDER BY t1."frpm count (k-12)" DESC LIMIT 5	california_schools
SELECT t2.school AS school, t1.avgscrwrite AS avgscrwrite FROM satscores AS t1 INNER JOIN schools AS t2 ON t1.cds = t2.cdscode WHERE t2.admfname1 = 'Ricci' AND t2.admlname1 = 'Ulrich'	california_schools
SELECT CAST(SUM(CASE WHEN schools.doc = 54 THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN schools.doc = 52 THEN 1 ELSE 0 END) AS _col_0 FROM schools AS schools WHERE schools.statustype = '已合并' AND schools.county = 'Orange'	california_schools
SELECT t2.school AS school, t1."frpm count (ages 5-17)" * 100 / t1."enrollment (ages 5-17)" AS _col_1 FROM frpm AS t1 INNER JOIN schools AS t2 ON t1.cdscode = t2.cdscode WHERE t2.county = 'Los Angeles' AND t2.gsserved = '幼儿园至9年级'	california_schools
SELECT t2.city AS city, COUNT(t2.cdscode) AS _col_1 FROM frpm AS t1 INNER JOIN schools AS t2 ON t1.cdscode = t2.cdscode WHERE t2.magnet = 1 AND t2.gsoffered = '幼儿园至8年级' AND t1."nslp provision status" = '多种供应条款类型' GROUP BY t2.city	california_schools
SELECT COUNT(t1.client_id) AS _col_0 FROM client AS t1 INNER JOIN district AS t2 ON t1.district_id = t2.district_id WHERE t1.gender = 'M' AND t2.a3 = '北波希米亚' AND t2.a11 > 8000	financial
SELECT t1.account_id AS account_id FROM account AS t1 INNER JOIN disp AS t2 ON t1.account_id = t2.account_id INNER JOIN client AS t3 ON t2.client_id = t3.client_id INNER JOIN district AS t4 ON t4.district_id = t1.district_id WHERE t2.client_id = (SELECT client.client_id AS client_id FROM client AS client ORDER BY client.birth_date DESC LIMIT 1) GROUP BY t4.a11, t1.account_id	financial
SELECT COUNT(t2.client_id) AS _col_0 FROM district AS t1 INNER JOIN client AS t2 ON t1.district_id = t2.district_id WHERE t2.gender = 'F' AND STRFTIME('%Y', t2.birth_date) < '1950' AND t1.a2 = '索科洛夫'	financial
SELECT t1.account_id AS account_id FROM trans AS t1 INNER JOIN account AS t2 ON t1.account_id = t2.account_id WHERE STRFTIME('%Y', t1.date) = '1998' AND t1.operation = '银行卡取款' AND t1.amount < (SELECT AVG(trans.amount) AS _col_0 FROM trans AS trans WHERE STRFTIME('%Y', trans.date) = '1998')	financial
SELECT t4.trans_id AS trans_id FROM client AS t1 INNER JOIN disp AS t2 ON t1.client_id = t2.client_id INNER JOIN account AS t3 ON t2.account_id = t3.account_id INNER JOIN trans AS t4 ON t3.account_id = t4.account_id WHERE t1.client_id = 3356 AND t4.operation = '取款'	financial
SELECT CAST(SUM(t1.gender = 'M') AS REAL) * 100 / COUNT(t1.client_id) AS _col_0 FROM client AS t1 INNER JOIN district AS t3 ON t1.district_id = t3.district_id INNER JOIN account AS t2 ON t2.district_id = t3.district_id INNER JOIN disp AS t4 ON t1.client_id = t4.client_id AND t2.account_id = t4.account_id WHERE t2.frequency = '每周扣款'	financial
SELECT t1.client_id AS client_id, STRFTIME('%Y', CURRENT_TIMESTAMP) - STRFTIME('%Y', t3.birth_date) AS _col_1 FROM disp AS t1 INNER JOIN card AS t2 ON t2.disp_id = t1.disp_id INNER JOIN client AS t3 ON t1.client_id = t3.client_id WHERE t2.type = '金卡' AND t1.type = '所有人'	financial
SELECT t1.account_id AS account_id, t2.a2 AS a2, t2.a3 AS a3 FROM account AS t1 INNER JOIN district AS t2 ON t1.district_id = t2.district_id WHERE t1.frequency = '按交易额扣款' AND STRFTIME('%Y', t1.date) = '1993'	financial
SELECT t1.account_id AS account_id, t1.frequency AS frequency FROM account AS t1 INNER JOIN district AS t2 ON t1.district_id = t2.district_id WHERE t2.a3 = '东波希米亚' AND STRFTIME('%Y', t1.date) BETWEEN '1995' AND '2000'	financial
